"CHAMPS/SAM/title": "The Ferryman",
"CHAMPS/SAM/passive/name": "The Threshold",
"CHAMPS/SAM/passive/desc": "After casting an ability, the next basic attack deals +40% bonus damage (triggers once, 1 s internal cooldown).",
"CHAMPS/SAM/abil/0/name": "Open Threshold",
"CHAMPS/SAM/abil/0/desc": "An explosive rift that bursts on the first enemy hit.",
