"CHAMPS/KAREN/abil/0/name": "Steady Hand",
"CHAMPS/KAREN/abil/0/desc": "Heals a wounded ally.",
"CHAMPS/KAREN/abil/1/name": "Absolute Gaze",
"CHAMPS/KAREN/abil/1/desc": "A projectile that stuns the first enemy hit.",
