"CHAMPS/LUNDGREN/title": "The Stone Keeper",
"CHAMPS/LUNDGREN/passive/name": "Seven Centuries",
"CHAMPS/LUNDGREN/passive/desc": "Abilities apply Frost. At 3 stacks, the target is frozen for 1 s.",
"CHAMPS/LUNDGREN/abil/0/name": "Eyes of Ice",
