"CHAMPS/LUNDGREN/abil/1/desc": "Teleports, leaving a floral explosion behind.",
"CHAMPS/LUNDGREN/abil/2/name": "Orbiting Stones",
"CHAMPS/LUNDGREN/abil/2/desc": "The stones strike every enemy around him.",
"CHAMPS/LUNDGREN/abil/3/name": "When You Die",
"CHAMPS/LUNDGREN/abil/3/desc": "A delayed rain of ice over a large area.",
"CHAMPS/DARK/name": "Dark",
"CHAMPS/DARK/title": "Child of the Abyss",
"CHAMPS/DARK/passive/name": "Hunger of the Abyss",
"CHAMPS/DARK/passive/desc": "His basic attacks shred 6 armour for 4 s, stacking up to three times.",
"CHAMPS/DARK/abil/0/name": "Shadow Blade",
