"CHAMPS/SCHISSIN/name": "Schissin-Rouge",
"CHAMPS/SCHISSIN/title": "The Name in the Notebook",
"CHAMPS/SCHISSIN/passive/name": "The Red",
"CHAMPS/SCHISSIN/passive/desc": "Reflects 25% of damage taken back to melee attackers.",
"CHAMPS/SCHISSIN/abil/0/name": "Arrest",
"CHAMPS/SCHISSIN/abil/0/desc": "A short charge that pins the target to the ground.",
"CHAMPS/SCHISSIN/abil/1/name": "Red Cordon",
"CHAMPS/SCHISSIN/abil/1/desc": "Encircles: nearby enemies can no longer get around him.",
"CHAMPS/SCHISSIN/abil/2/name": "Old Guard",
"CHAMPS/SCHISSIN/abil/2/desc": "Armours up and regenerates while holding his ground.",
"CHAMPS/SCHISSIN/abil/3/name": "Case Closed",
