"CHAMPS/OUSMANE/name": "Ousmane",
"CHAMPS/OUSMANE/title": "Keeper of the Port",
"CHAMPS/OUSMANE/passive/name": "Old Friend",
"CHAMPS/OUSMANE/passive/desc": "+18% damage against targets below 40% HP: he finishes what he starts.",
"CHAMPS/OUSMANE/abil/0/name": "Warning Shot",
"CHAMPS/OUSMANE/abil/0/desc": "A tracer round that pierces the line.",
