"CHAMPS/SUB/name": "Sub",
"CHAMPS/SUB/title": "The Operator",
"CHAMPS/SUB/passive/name": "Six Months in Abidjan",
"CHAMPS/SUB/passive/desc": "He has scouted everything: 15% critical chance and 10% armour penetration.",
"CHAMPS/SUB/abil/0/name": "Clean Cut",
"CHAMPS/SUB/abil/0/desc": "A thrown blade that cuts through the ranks.",
"CHAMPS/SUB/abil/1/name": "Erasure",
