"CHAMPS/GROB/passive/name": "Dead Weight",
"CHAMPS/GROB/passive/desc": "Reflects 20% of damage taken and loses 20% of his cooldowns on each takedown.",
"CHAMPS/GROB/abil/0/name": "Backhand",
