"CHAMPS/KRAG/name": "Krag",
"CHAMPS/KRAG/title": "The Obsidian Plate",
"CHAMPS/KRAG/passive/name": "Built for Pressure",
"CHAMPS/KRAG/passive/desc": "Resists 40% of crowd-control duration: nothing stops him for long.",
"CHAMPS/KRAG/abil/0/name": "Seabed Fist",
"CHAMPS/KRAG/abil/0/desc": "Strikes the ground: a shockwave that knocks up everything around him.",
